"""Build permanent source-complete records for selected archived meetings."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
BRIEFINGS = ROOT / "docs" / "briefings"
MEETINGS = {
    "2025-11-18": ("November 18, 2025", "BI_NOVEMBER_18_2025_SOURCES", "qfbPJv8BP0U", "Capital planning, special-event rules, holiday lighting, transportation coordination, public safety systems, and City travel policy."),
    "2025-12-02": ("December 2, 2025", "BI_DECEMBER_2_2025_SOURCES", "cfqIZpAQfg4", "Zoning and food-truck rules, housing-property standards, community grants, City administration, animal control, police technology, and Potrero mitigation."),
    "2025-12-16": ("December 16, 2025", "BI_DECEMBER_16_2025_SOURCES", "GjLWN4HiGxI", "Community facilities districts, housing maps, transportation mitigation, appointments, the Cherry Festival, billboards, downtown crosswalks, financial reporting, and City staffing."),
}

STYLE = """
.record-hero{background:linear-gradient(125deg,#092b58,#174d82);color:#fff;padding:54px 0}.record-hero h1{color:#fff;font-size:clamp(2.35rem,6vw,4rem);margin:.12em 0}.record-hero p{color:#e1ebf5}.record-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}.summary-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.summary-grid div{border:1px solid var(--line);border-radius:12px;padding:17px;background:#fff}.summary-grid strong,.summary-grid span{display:block}.summary-grid strong{font-size:1.5rem;color:var(--navy)}.summary-grid span{color:var(--muted);font-size:.84rem}.calendar{margin-top:20px}.calendar>summary{cursor:pointer;background:var(--navy);color:#fff;border-radius:12px;padding:17px 20px;font-weight:900}.calendar-body{border:1px solid var(--line);padding:14px;background:var(--soft)}.agenda-record{margin:10px 0;border:1px solid var(--line);border-radius:10px;background:#fff}.agenda-record>summary{cursor:pointer;display:grid;grid-template-columns:62px 1fr auto;gap:12px;padding:14px;list-style:none}.agenda-record>summary:after{content:'+'}.agenda-record[open]>summary:after{content:'−'}.agenda-number{color:var(--red);font-weight:900}.agenda-title{font-weight:850}.agenda-documents{border-top:1px solid var(--line);padding:6px 14px}.agenda-document{display:flex;justify-content:space-between;gap:14px;align-items:center;padding:10px 0;border-bottom:1px solid var(--line)}.viewer-dialog{width:min(1180px,96vw);height:92vh;border:0;border-radius:14px;padding:0}.viewer-dialog::backdrop{background:#001b3dcc}.viewer-dialog header{height:58px;display:flex;align-items:center;justify-content:space-between;padding:0 16px}.viewer-dialog iframe{width:100%;height:calc(92vh - 58px);border:0}@media(max-width:700px){.summary-grid{grid-template-columns:1fr 1fr}.agenda-document{align-items:flex-start;flex-direction:column}}
"""

SCRIPT = """(()=>{const D=window.VARIABLE,O=['Public Hearing','Action','Consent'],out=document.querySelector('#calendar-results'),dialog=document.querySelector('#viewer-dialog'),frame=document.querySelector('#viewer-frame'),title=document.querySelector('#viewer-title');const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const itemTitle=f=>(f.find(x=>/staff report/i.test(x.title))||f[0]).title.replace(/^staff report\\s*[-–:]?\\s*/i,'');out.innerHTML=O.map(s=>{const d=D.filter(x=>x.section===s);if(!d.length)return'';const g=Object.groupBy(d,x=>x.item);return `<details class="calendar"><summary>${esc(s)} calendar · ${Object.keys(g).length} items · ${d.length} documents</summary><div class="calendar-body">${Object.entries(g).map(([i,f])=>`<details class="agenda-record"><summary><span class="agenda-number">${esc(i)}</span><span class="agenda-title">${esc(itemTitle(f))}</span></summary><div class="agenda-documents">${f.map(x=>`<div class="agenda-document"><span>${esc(x.title)}</span><button class="btn small" data-url="${esc(x.archiveUrl)}" data-title="${esc(x.title)}">View document</button></div>`).join('')}</div></details>`).join('')}</div></details>`}).join('');out.onclick=e=>{const b=e.target.closest('[data-url]');if(!b)return;title.textContent=b.dataset.title;const back=new URL('DATE.html',location.href).href;frame.src=`../documents/viewer.html?url=${encodeURIComponent(b.dataset.url)}&title=${encodeURIComponent(b.dataset.title)}&returnUrl=${encodeURIComponent(back)}&returnLabel=${encodeURIComponent('Back to LABEL meeting record')}`;dialog.showModal()};document.querySelector('#viewer-close').onclick=()=>{dialog.close();frame.src='about:blank'}})();"""

for date, (label, variable, video_id, topics) in MEETINGS.items():
    raw = (BRIEFINGS / f"{date}-sources.js").read_text(encoding="utf-8")
    data = json.loads(raw[raw.index("=") + 1:].rstrip(";\n"))
    counts = {section: len({d["item"] for d in data if d["section"] == section}) for section in ("Public Hearing", "Action", "Consent")}
    html = f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{label} Council Meeting Record | Beaumont Intelligence</title><meta name="description" content="Source-complete record for the {label} Beaumont City Council meeting."><link href="../favicon.png" rel="icon"><link href="../styles.css" rel="stylesheet"><link href="../meeting-records.css" rel="stylesheet"><script defer src="../app.js"></script><style>{STYLE}</style></head><body data-page="briefing"><a class="skip-link" href="#main">Skip to content</a><div class="preview-banner"><strong>Meeting complete</strong><span>Full video, transcript, agenda packet, and voting-calendar documents collected</span></div><header class="app-header"><div class="wrap header-row"><a aria-label="Beaumont Intelligence home" class="brand" href="../index.html"><img class="brand-logo" src="../mbf-logo.png" alt=""><span class="brand-copy"><strong><span class="red">BEAUMONT</span> <span class="blue">INTELLIGENCE</span></strong><small>Council Intelligence</small></span></a><button aria-controls="primary-nav" aria-expanded="false" class="menu-button" id="menu-button">Menu</button><nav class="primary-nav" id="primary-nav" aria-label="Primary navigation"><a href="../index.html">Home</a><a aria-current="page" href="../council-intelligence.html">Council Intelligence</a><a href="../intelligence-centers.html">Intelligence Centers</a><a href="../documents/index.html">Research Library</a><a href="../about.html">About</a></nav></div></header><main><section class="record-hero"><div class="wrap narrow"><div class="eyebrow light">Permanent Council meeting record</div><h1>{label}</h1><p>{topics}</p><div class="record-actions"><a class="btn" href="{date}-sources.html">Open interactive agenda</a><a class="btn ghost-light" href="https://www.youtube.com/watch?v={video_id}" target="_blank" rel="noopener">Full meeting video ↗</a></div></div></section><section class="section compact alt"><div class="wrap"><div class="summary-grid"><div><strong>{len(data)}</strong><span>Voting-calendar documents</span></div><div><strong>{counts['Public Hearing']}</strong><span>Public hearing items</span></div><div><strong>{counts['Action']}</strong><span>Action items</span></div><div><strong>{counts['Consent']}</strong><span>Consent items</span></div></div></div></section><section class="section compact"><div class="wrap narrow"><div class="eyebrow">Complete source file</div><h2>Agenda, attachments, video, and transcript are collected</h2><p class="lead-copy">Every Public Hearing, Action, and Consent calendar document found in the agenda packet is archived below. The meeting transcript is indexed for word-and-phrase searches in the Research Library.</p><div class="status-actions"><a class="btn" href="../documents/index.html">Search the Research Library</a></div></div></section><section class="section compact alt"><div class="wrap"><div class="eyebrow">Complete meeting file</div><h2>All voting-calendar documents</h2><p>Expand a calendar and item to open every archived staff report and attachment.</p><div id="calendar-results"></div></div></section></main><dialog class="viewer-dialog" id="viewer-dialog"><header><strong id="viewer-title">Document viewer</strong><button class="btn small" id="viewer-close">Close ×</button></header><iframe id="viewer-frame" title="Document viewer"></iframe></dialog><script src="{date}-sources.js"></script><script>{SCRIPT.replace('VARIABLE', variable).replace('DATE', date).replace('LABEL', label)}</script></body></html>"""
    (BRIEFINGS / f"{date}.html").write_text(html, encoding="utf-8")
    print(f"Built {date} source-complete meeting record")
